CREATE TABLE IF NOT EXISTS airport_observations (metric_version TEXT NOT NULL,source_id TEXT NOT NULL,run_id TEXT NOT NULL,service_date TEXT NOT NULL,hour_kst INTEGER NOT NULL,minute_bucket INTEGER NOT NULL,observed_at TEXT NOT NULL,observation_bucket TEXT NOT NULL,airport_iata TEXT NOT NULL,direction TEXT NOT NULL,known_count INTEGER NOT NULL,unknown_count INTEGER NOT NULL,delayed_count INTEGER NOT NULL,cancelled_count INTEGER NOT NULL,PRIMARY KEY(metric_version,source_id,observation_bucket,airport_iata,direction));
CREATE INDEX IF NOT EXISTS idx_airport_observations_comparison ON airport_observations(airport_iata,direction,hour_kst,minute_bucket,service_date);
